import React, { useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useHistory } from 'react-router-dom';
import { Paper } from '@material-ui/core';
import DeleteOutlineIcon from '@material-ui/icons/DeleteOutline';
import moment from 'moment';
import CustomSelect from 'components/CustomSelect';
import CustomButton from 'components/CustomButton';
import CustomInput from 'views/admin/Common/CustomInput';
import ConfirmModal from 'views/admin/Common/ConfirmModal';
import colors from 'config/colors';
import { courseStatic, employeeStatic } from 'config/constants';
import {
  formCourseSelectList,
  formEmpSelectList,
  formResMessage,
  formStudentSelectList,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
  getLoggedUserUtils,
} from 'utils/commonFunc';
import {
  addOrUpdateAppreciationTemplateService,
  deleteAppreciationTemplateService,
  fetchAllAppreciationTemplatesService,
  fetchReceivedAppreciationsApi,
  saveAppreciationAsDraftService,
  sendAppreciationCardService,
} from 'actions/admin/schools';
import { fetchBatchCourseService } from 'actions/admin/courses';
import { fetchSchoolCourseStudentsService } from 'actions/admin/students';
import { fetchSchoolEmployeesApi } from 'actions/admin/employees';
import { showToast } from 'actions/admin/auth';
import { initialAppreciationState } from './AppreciationTemplate';

const MAX_MESSAGE = 300;
const THEMES = [
  { name: 'Gold', color: '#FFA500' },
  { name: 'Purple', color: '#7B1FA2' },
  { name: 'Blue', color: '#1565C0' },
  { name: 'Green', color: '#2E7D32' },
  { name: 'Red', color: '#C62828' },
  { name: 'Teal', color: '#00838F' },
];
const ICONS = [
  { name: 'Award', value: 'fas fa-award' },
  { name: 'Trophy', value: 'fas fa-trophy' },
  { name: 'Medal', value: 'fas fa-medal' },
  { name: 'Star', value: 'fas fa-star' },
  { name: 'Graduate', value: 'fas fa-graduation-cap' },
];
const TITLE_IDEAS = ['Best Performer Award', 'Star of the Week', 'Excellent Behaviour', 'Great Improvement'];
const DEFAULT_MESSAGE = 'for outstanding performance and dedication. Keep up the great work!';

const STUDENT = 'STUDENT';
// What the backend stores as `toWhom` for a template: STUDENT, or the (configurable) teacher label.
const isStudentTarget = toWhom => toWhom === STUDENT;

// The card as the existing template/print page stores it, filled from the few things the page asks for.
const buildAppreciation = ({ design, target, recipientName, by, designation, schoolName }) => {
  const base = initialAppreciationState;
  return {
    ...base,
    toWhom: target === STUDENT ? STUDENT : employeeStatic,
    headerIcon: {
      ...base.headerIcon,
      fieldValue: design.icon,
      style: { ...base.headerIcon.style, color: design.color },
    },
    certificateStyle: { ...base.certificateStyle, borderColor: design.color },
    schoolName: { ...base.schoolName, fieldValue: schoolName },
    certificationName: { ...base.certificationName, fieldValue: design.title },
    description: { ...base.description, fieldValue: design.message },
    activityDate: { ...base.activityDate, fieldValue: moment().format('YYYY-MM-DD') },
    fromUser: { ...base.fromUser, fieldValue: by },
    fromUserDesignation: { ...base.fromUserDesignation, fieldValue: designation },
    toUser: {
      ...base.toUser,
      fieldValue: recipientName || (target === STUDENT ? 'Student name here' : `${employeeStatic} name here`),
      style: { ...base.toUser.style, color: design.color },
    },
  };
};

// What makes two cards "the same design", so a card that matches a saved template reuses it instead of adding another.
const designKey = a => {
  const json = typeof a === 'string' ? safeParse(a) : a || {};
  return JSON.stringify([
    json.certificationName?.fieldValue,
    json.description?.fieldValue,
    json.certificateStyle?.borderColor,
    json.headerIcon?.fieldValue,
    json.fromUser?.fieldValue,
    json.fromUserDesignation?.fieldValue,
  ]);
};
const safeParse = text => {
  try {
    return JSON.parse(text);
  } catch (e) {
    return {};
  }
};

// The card as the person will receive it.
const CardPreview = ({ design, recipientName, by, designation, schoolName }) => (
  <div
    style={{
      background: '#fff',
      border: `4px solid ${design.color}`,
      borderRadius: 8,
      padding: '22px 20px',
      textAlign: 'center',
      boxShadow: '0 2px 10px rgba(0,0,0,0.08)',
    }}>
    <i className={design.icon} aria-hidden="true" style={{ fontSize: 38, color: design.color }} />
    <div style={{ marginTop: 8, fontSize: 13, fontWeight: 'bold', color: '#9a9a9a' }}>{schoolName}</div>
    <div
      style={{
        marginTop: 10,
        fontSize: 22,
        fontWeight: 'bolder',
        textTransform: 'uppercase',
        fontFamily: 'Times New Roman, serif',
        color: '#222',
      }}>
      {design.title || 'Award title'}
    </div>
    <div style={{ marginTop: 14, fontSize: 12, color: '#777' }}>Presented to</div>
    <div style={{ fontSize: 19, fontWeight: 'bold', color: design.color }}>
      {recipientName || 'Name of the recipient'}
    </div>
    <div style={{ marginTop: 10, fontSize: 14, color: '#333', whiteSpace: 'pre-wrap' }}>{design.message}</div>
    <div style={{ marginTop: 16, fontSize: 12, color: '#777' }}>{moment().format('MMMM YYYY')}</div>
    <div style={{ marginTop: 12, fontWeight: 'bold', fontSize: 14 }}>{by || 'Name'}</div>
    <div style={{ fontSize: 12.5, color: '#555' }}>{designation}</div>
  </div>
);

// Appreciation cards on one page: choose who it is for, write or pick the card, and send. A card you send is kept as a
// template (the saved cards on the right), so the next time you can pick it again or start a new one.
const Appreciations = () => {
  const dispatch = useDispatch();
  const history = useHistory();
  const loggedUserToken = useSelector(state => state.auth.loggedUserToken);
  const loggedUserId = useSelector(state => state.auth.loggedUserId);
  const loggedUserRole = useSelector(state => state.auth.loggedUserRole);
  const courseList = useSelector(state => state.courses.batchCourseList) || [];
  const courseStudentList = useSelector(state => state.schools.courseStudentList) || [];
  const templates = useSelector(state => state.schools.appreciationTemplates) || [];
  const loggedUser = getLoggedUserUtils();
  const school = getGlobalSchoolUtils();

  const [target, setTarget] = useState(STUDENT);
  const [courseId, setCourseId] = useState(0);
  const [studentId, setStudentId] = useState(0);
  const [employees, setEmployees] = useState([]);
  const [employeeId, setEmployeeId] = useState(0);
  const [design, setDesign] = useState({
    title: TITLE_IDEAS[0],
    message: DEFAULT_MESSAGE,
    color: THEMES[0].color,
    icon: ICONS[0].value,
  });
  const [by, setBy] = useState(loggedUser?.fullName || '');
  const [designation, setDesignation] = useState(loggedUserRole === 'ROLE_TEACHER' ? employeeStatic : 'Principal');
  const [loadedTemplateId, setLoadedTemplateId] = useState(null);
  const [recent, setRecent] = useState([]);
  const [isSending, setIsSending] = useState(false);
  const [templateToDelete, setTemplateToDelete] = useState(null);

  const courseOptions = useMemo(() => formCourseSelectList(courseList), [courseList]);
  const studentOptions = useMemo(() => formStudentSelectList(courseStudentList), [courseStudentList]);
  const employeeOptions = useMemo(() => formEmpSelectList(employees), [employees]);
  const recipientName =
    target === STUDENT
      ? studentOptions.find(el => el.value === studentId)?.name
      : employeeOptions.find(el => el.value === employeeId)?.name;
  const recipientId = target === STUDENT ? studentId : employeeId;
  const toWhom = target === STUDENT ? STUDENT : employeeStatic;
  const savedForTarget = templates.filter(t =>
    target === STUDENT ? isStudentTarget(t.toWhom) : !isStudentTarget(t.toWhom)
  );

  const loadTemplates = () =>
    fetchAllAppreciationTemplatesService({ dispatch, token: loggedUserToken, schoolId: school?.schoolId });

  useEffect(() => {
    loadTemplates();
    const batch = getGlobalCurrentBatchUtils();
    dispatch(
      fetchBatchCourseService({
        token: loggedUserToken,
        schoolId: school?.schoolId,
        batchId: batch?.batchId,
        status: 'ACTIVE',
      })
    );
  }, []);

  useEffect(() => {
    if (!courseId && courseList.length) setCourseId(courseList[0].courseId);
  }, [courseList]);

  useEffect(() => {
    if (!courseId) return;
    const batch = getGlobalCurrentBatchUtils();
    setStudentId(0);
    dispatch(fetchSchoolCourseStudentsService({ token: loggedUserToken, batchId: batch?.batchId, courseId }));
  }, [courseId]);

  useEffect(() => {
    if (target !== STUDENT && !employees.length) {
      const batch = getGlobalCurrentBatchUtils();
      fetchSchoolEmployeesApi({
        token: loggedUserToken,
        schoolId: school?.schoolId,
        batchId: batch?.batchId,
        profession: 'TEACHING',
      }).then(list => setEmployees(list || []));
    }
  }, [target]);

  // what was already sent to the chosen person
  const loadRecent = async () => {
    if (!recipientId) {
      setRecent([]);
      return;
    }
    const batch = getGlobalCurrentBatchUtils();
    const list = await fetchReceivedAppreciationsApi({
      token: loggedUserToken,
      userId: recipientId,
      batchId: batch?.batchId,
      roleName: target === STUDENT ? 'ROLE_STUDENT' : 'ROLE_TEACHER',
    });
    setRecent(Array.isArray(list) ? list : []);
  };
  useEffect(() => {
    loadRecent();
  }, [recipientId, target]);

  const changeDesign = patch => {
    setDesign(prev => ({ ...prev, ...patch }));
  };

  const useTemplate = template => {
    const json = safeParse(template.templateJson);
    setDesign({
      title: json.certificationName?.fieldValue || '',
      message: json.description?.fieldValue || '',
      color: json.certificateStyle?.borderColor || THEMES[0].color,
      icon: json.headerIcon?.fieldValue || ICONS[0].value,
    });
    if (json.fromUser?.fieldValue && json.fromUser.fieldValue !== 'Provider name here') setBy(json.fromUser.fieldValue);
    if (json.fromUserDesignation?.fieldValue) setDesignation(json.fromUserDesignation.fieldValue);
    setLoadedTemplateId(template.appreTemplateId);
  };

  const startBlank = () => {
    setDesign({ title: '', message: '', color: THEMES[0].color, icon: ICONS[0].value });
    setLoadedTemplateId(null);
  };

  const deleteTemplate = async () => {
    try {
      await deleteAppreciationTemplateService({ token: loggedUserToken, appreTemplateId: templateToDelete });
      if (loadedTemplateId === templateToDelete) setLoadedTemplateId(null);
      loadTemplates();
    } catch (err) {
      dispatch(showToast(formResMessage(err), 'error'));
    }
    setTemplateToDelete(null);
  };

  // The saved template this card is (or becomes): the same design as one that exists is reused, otherwise it is saved.
  const templateIdFor = async appreciation => {
    const key = designKey(appreciation);
    const same = templates.find(
      t => isStudentTarget(t.toWhom) === (target === STUDENT) && designKey(t.templateJson) === key
    );
    if (same) return same.appreTemplateId;
    // the template shows its recipient as a placeholder, the name is filled in when the card is sent
    const generic = buildAppreciation({
      design,
      target,
      recipientName: '',
      by,
      designation,
      schoolName: school?.schoolName,
    });
    await addOrUpdateAppreciationTemplateService({
      appreciation: generic,
      action: 'create',
      token: loggedUserToken,
      schoolId: school?.schoolId,
    });
    const fresh = (await loadTemplates()) || [];
    const created = fresh
      .filter(t => designKey(t.templateJson) === key)
      .sort((a, b) => b.appreTemplateId - a.appreTemplateId)[0];
    if (!created) throw new Error('The card could not be saved as a template');
    return created.appreTemplateId;
  };

  const canSend = !!recipientId && !!design.title.trim() && !!design.message.trim() && !isSending;

  const send = async () => {
    const batch = getGlobalCurrentBatchUtils();
    setIsSending(true);
    try {
      const appreciation = buildAppreciation({
        design,
        target,
        recipientName,
        by,
        designation,
        schoolName: school?.schoolName,
      });
      const templateId = await templateIdFor(appreciation);
      const toUserRole = target === STUDENT ? 'ROLE_STUDENT' : 'ROLE_TEACHER';
      const draft = await saveAppreciationAsDraftService({
        appreciationCard: {
          activityDate: moment().format('YYYY-MM-DD'),
          appreciationId: 0,
          batchId: batch?.batchId,
          description: design.message.trim(),
          fromUserId: loggedUserId,
          fromUserRole: loggedUserRole,
          heading: design.title.trim(),
          schoolId: school?.schoolId,
          status: 'DRAFT',
          templateId,
          templateType: 'NO_URL',
          toUserId: recipientId,
          toUserRole,
        },
        batchId: batch?.batchId,
        schoolId: school?.schoolId,
        token: loggedUserToken,
      });
      await sendAppreciationCardService({
        appreciationCard: { appreciationId: draft?.appreciationId, toUserId: recipientId, toUserRole },
        schoolId: school?.schoolId,
        token: loggedUserToken,
      });
      setLoadedTemplateId(templateId);
      dispatch(showToast(`Appreciation sent to ${recipientName}`, 'success'));
      loadRecent();
    } catch (err) {
      dispatch(showToast(formResMessage(err), 'error'));
    }
    setIsSending(false);
  };

  const chip = (selected, color, onClick, label, key) => (
    <button
      key={key}
      type="button"
      onClick={onClick}
      style={{
        border: `1px solid ${selected ? color : '#e2d9ea'}`,
        background: selected ? color : '#fff',
        color: selected ? '#fff' : colors.grey1,
        borderRadius: 14,
        padding: '2px 12px',
        fontSize: 12.5,
        fontWeight: 'bold',
        cursor: 'pointer',
      }}>
      {label}
    </button>
  );

  return (
    <div className="content">
      <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start', flexWrap: 'wrap' }}>
        {/* write and send the card */}
        <Paper elevation={3} style={{ flex: '3 1 480px', minWidth: 0, borderRadius: 12, padding: 20 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap', marginBottom: 12 }}>
            <b style={{ fontSize: 16, color: colors.accentDark }}>Appreciation card</b>
            <span
              style={{ display: 'inline-flex', padding: 3, borderRadius: 20, background: colors.sidebarActiveItemBg }}>
              {[
                { key: STUDENT, label: 'For a student' },
                { key: employeeStatic, label: `For a ${employeeStatic.toLowerCase()}` },
              ].map(option => (
                <button
                  key={option.key}
                  type="button"
                  onClick={() => {
                    setTarget(option.key === STUDENT ? STUDENT : 'TEACHER');
                    setLoadedTemplateId(null);
                  }}
                  style={{
                    border: 0,
                    borderRadius: 17,
                    padding: '4px 14px',
                    fontSize: 13,
                    fontWeight: 'bold',
                    cursor: 'pointer',
                    color: (option.key === STUDENT) === (target === STUDENT) ? colors.accent : colors.accentDark,
                    opacity: (option.key === STUDENT) === (target === STUDENT) ? 1 : 0.75,
                    background: (option.key === STUDENT) === (target === STUDENT) ? '#fff' : 'transparent',
                    boxShadow:
                      (option.key === STUDENT) === (target === STUDENT) ? '0 1px 4px rgba(91,21,132,0.25)' : 'none',
                  }}>
                  {option.label}
                </button>
              ))}
            </span>
          </div>

          <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
            {target === STUDENT ? (
              <>
                <div style={{ flex: '1 1 200px' }}>
                  <CustomSelect
                    name="courseId"
                    label={courseStatic}
                    value={courseId}
                    onChange={(name, value) => setCourseId(value)}
                    options={courseOptions}
                    applyLabelStyle={true}
                  />
                </div>
                <div style={{ flex: '1 1 200px' }}>
                  <CustomSelect
                    name="studentId"
                    label="Student"
                    value={studentId || null}
                    onChange={(name, value) => setStudentId(value)}
                    options={studentOptions}
                    applyLabelStyle={true}
                  />
                </div>
              </>
            ) : (
              <div style={{ flex: '1 1 300px' }}>
                <CustomSelect
                  name="employeeId"
                  label={employeeStatic}
                  value={employeeId || null}
                  onChange={(name, value) => setEmployeeId(value)}
                  options={employeeOptions}
                  applyLabelStyle={true}
                />
              </div>
            )}
          </div>

          <div style={{ display: 'flex', gap: 20, flexWrap: 'wrap', marginTop: 6 }}>
            {/* the card's words and look */}
            <div style={{ flex: '1 1 260px', minWidth: 0 }}>
              <CustomInput
                label="Title"
                name="title"
                value={design.title}
                onChange={(name, value) => changeDesign({ title: String(value).slice(0, 60) })}
              />
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, margin: '-6px 0 10px' }}>
                {TITLE_IDEAS.map(idea =>
                  chip(design.title === idea, design.color, () => changeDesign({ title: idea }), idea, idea)
                )}
              </div>
              <CustomInput
                label="Message"
                type="textarea"
                name="message"
                rows="3"
                value={design.message}
                onChange={(name, value) => changeDesign({ message: String(value).slice(0, MAX_MESSAGE) })}
              />
              <div style={{ fontSize: 11.5, color: colors.grey3, margin: '-6px 0 10px', textAlign: 'right' }}>
                {design.message.length}/{MAX_MESSAGE}
              </div>
              <div style={{ display: 'flex', gap: 10 }}>
                <div style={{ flex: 1 }}>
                  <CustomInput label="From" name="by" value={by} onChange={(name, value) => setBy(value)} />
                </div>
                <div style={{ flex: 1 }}>
                  <CustomInput
                    label="Designation"
                    name="designation"
                    value={designation}
                    onChange={(name, value) => setDesignation(value)}
                  />
                </div>
              </div>
              <div style={{ fontSize: 12, fontWeight: 'bold', color: colors.grey2, marginBottom: 4 }}>Colour</div>
              <div style={{ display: 'flex', gap: 8, marginBottom: 10 }}>
                {THEMES.map(theme => (
                  <button
                    key={theme.color}
                    type="button"
                    title={theme.name}
                    aria-label={theme.name}
                    onClick={() => changeDesign({ color: theme.color })}
                    style={{
                      width: 26,
                      height: 26,
                      borderRadius: '50%',
                      background: theme.color,
                      cursor: 'pointer',
                      border: design.color === theme.color ? '3px solid #fff' : '2px solid transparent',
                      boxShadow: design.color === theme.color ? `0 0 0 2px ${theme.color}` : 'none',
                    }}
                  />
                ))}
              </div>
              <div style={{ fontSize: 12, fontWeight: 'bold', color: colors.grey2, marginBottom: 4 }}>Icon</div>
              <div style={{ display: 'flex', gap: 8 }}>
                {ICONS.map(icon => (
                  <button
                    key={icon.value}
                    type="button"
                    title={icon.name}
                    aria-label={icon.name}
                    onClick={() => changeDesign({ icon: icon.value })}
                    style={{
                      width: 34,
                      height: 34,
                      borderRadius: 8,
                      cursor: 'pointer',
                      border: `1px solid ${design.icon === icon.value ? design.color : '#e2d9ea'}`,
                      background: design.icon === icon.value ? `${design.color}14` : '#fff',
                      color: design.color,
                    }}>
                    <i className={icon.value} aria-hidden="true" />
                  </button>
                ))}
              </div>
            </div>
            <div style={{ flex: '1 1 260px', minWidth: 0 }}>
              <CardPreview
                design={design}
                recipientName={recipientName}
                by={by}
                designation={designation}
                schoolName={school?.schoolName}
              />
            </div>
          </div>

          <div
            style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, marginTop: 16 }}>
            <span style={{ fontSize: 12, color: colors.grey3 }}>
              The card is sent to the {toWhom === STUDENT ? "student's guardian" : employeeStatic.toLowerCase()} and the
              design is kept under Saved cards.
            </span>
            <CustomButton name="Send" onClick={send} disabled={!canSend} loading={isSending} showLoader={true} />
          </div>

          {!!recipientId && (
            <div style={{ marginTop: 20 }}>
              <b style={{ fontSize: 14 }}>Sent to {recipientName}</b>
              {recent.length ? (
                recent.map(card => (
                  <div
                    key={card.appreciationId}
                    style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      gap: 8,
                      padding: '8px 0',
                      borderTop: '1px solid #f0eaf5',
                    }}>
                    <div style={{ minWidth: 0 }}>
                      <div style={{ fontSize: 13.5, fontWeight: 600 }}>{card.heading}</div>
                      <div style={{ fontSize: 12, color: colors.grey3 }}>{card.description}</div>
                    </div>
                    <a
                      href="#view"
                      onClick={e => {
                        e.preventDefault();
                        history.push(
                          `/admin/appreciations/appreciation-template?appreTemplateId=${card.templateId}&action=sent&appreciationId=${card.appreciationId}`
                        );
                      }}
                      style={{ fontSize: 12, fontWeight: 'bold', whiteSpace: 'nowrap', color: colors.accent }}>
                      View / Print
                    </a>
                  </div>
                ))
              ) : (
                <div style={{ fontSize: 12.5, color: colors.grey3, marginTop: 4 }}>
                  Nothing sent to {recipientName} yet.
                </div>
              )}
            </div>
          )}
        </Paper>

        {/* the cards saved before */}
        <Paper elevation={3} style={{ flex: '1 1 260px', minWidth: 0, borderRadius: 12, padding: 16 }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
            <b style={{ fontSize: 15 }}>Saved cards</b>
            <CustomButton size="small" variant="outlined" name="+ New card" onClick={startBlank} />
          </div>
          {savedForTarget.length ? (
            savedForTarget.map(template => {
              const json = safeParse(template.templateJson);
              const color = json.certificateStyle?.borderColor || colors.accent;
              const active = loadedTemplateId === template.appreTemplateId;
              return (
                <div
                  key={template.appreTemplateId}
                  role="button"
                  tabIndex={0}
                  onClick={() => useTemplate(template)}
                  onKeyDown={e => e.key === 'Enter' && useTemplate(template)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 10,
                    padding: '8px 10px',
                    marginBottom: 6,
                    borderRadius: 8,
                    cursor: 'pointer',
                    border: `1px solid ${active ? color : '#ece6f2'}`,
                    borderLeft: `4px solid ${color}`,
                    background: active ? `${color}0f` : '#fff',
                  }}>
                  <i
                    className={json.headerIcon?.fieldValue || 'fas fa-award'}
                    aria-hidden="true"
                    style={{ color, fontSize: 20 }}
                  />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div
                      style={{
                        fontWeight: 'bold',
                        fontSize: 13.5,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}>
                      {json.certificationName?.fieldValue || 'Untitled'}
                    </div>
                    <div
                      style={{
                        fontSize: 11.5,
                        color: colors.grey3,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}>
                      {json.description?.fieldValue}
                    </div>
                  </div>
                  <button
                    type="button"
                    aria-label="Delete"
                    onClick={e => {
                      e.stopPropagation();
                      setTemplateToDelete(template.appreTemplateId);
                    }}
                    style={{ border: 0, background: 'none', color: '#c62828', cursor: 'pointer', padding: 2 }}>
                    <DeleteOutlineIcon style={{ fontSize: 18 }} />
                  </button>
                </div>
              );
            })
          ) : (
            <div style={{ fontSize: 13, color: colors.grey3, padding: '12px 0' }}>
              No saved cards yet. A card you send is saved here for next time.
            </div>
          )}
        </Paper>
      </div>
      <ConfirmModal
        confirmModalOpen={!!templateToDelete}
        deleteConfirm={deleteTemplate}
        deleteCancel={() => setTemplateToDelete(null)}
        confirmMessage="Delete this saved card?"
      />
    </div>
  );
};

export default Appreciations;
