import React from 'react';
import { Modal, ModalHeader, ModalBody, Row } from 'reactstrap';
import CustomButton from '../../../components/CustomButton';

const ConfirmModal = ({
  loading,
  size = 'sm',
  headerStyle,
  confirmModalOpen,
  deleteConfirm,
  deleteCancel,
  confirmMessage,
}) => (
  <Modal size={size} isOpen={confirmModalOpen}>
    <ModalHeader style={{ textAlign: 'center' }}>
      <span style={headerStyle}>{confirmMessage || 'Are you sure you want to remove ?'}</span>
    </ModalHeader>
    <ModalBody>
      <Row style={{ textAlign: 'center', justifyContent: 'center' }}>
        <CustomButton
          onClick={() => deleteConfirm()}
          name="Yes"
          showLoader={true}
          disabled={loading}
          loading={loading}
        />{' '}
        <CustomButton className="ml-2" color="default" onClick={() => deleteCancel()} name="No" />
      </Row>
    </ModalBody>
  </Modal>
);

export default ConfirmModal;
